`timescale 1ns / 1ps
//==========================================================================
// phase7_link_top_tb
//
// Phase 7 round 2, end to end over real bit-serial UART: a mock PC (its own
// uart_tx/uart_rx, cross-wired to the DUT, 2 Mbaud to keep the run short)
// loads config/phase7_seq_loopback.yaml's table into the DUT's RAM, then
// runs it, the way tools/nemo_ctl/link.py's SeqLink does. The table comes
// from package phase7_link_tb_pkg, generated by `gen_svh.py --phase7-link
// --table-out <file> --time-scale 1e-4` (scripts/run_phase7_sim.sh);
// expected step lengths are read back out of it, so the checks don't
// hard-code the scale.
//
// The 5 loopback jumpers are modelled (fmc_pins[i+16] = fmc_pins[i]); a
// pulled jumper reads 0.
//
//   1. echo (SCRATCH), load 6 steps + N_STEPS, APPLY -> pins at step 0's idle
//   2. RUN: step lengths exact (steps 0, 1 = their AFTER ticks), rst pulse,
//      8 clk edges; STATUS done, LATE set (step 4 "confirm" ends on its 3rd
//      tick, before the bank can fetch step 5 -- expected, it's what LATE is
//      for); data_in read back over the link = 0xA5
//   3. N_STEPS / table write while running -> refused, TABLE_REJECTED,
//      cleared by a STATUS write
//   4. jumper J2-20 pulled -> FAULT, LAST_STEP 4
//   5. STOP during step 2 -> ABORTED, LAST_STEP 2
//==========================================================================
module phase7_link_top_tb;

    localparam int BAUD = 2_000_000;      // 50 ticks per bit
    localparam int EB   = phase7_link_pkg::ENTRY_BYTES;
    localparam int UB   = phase7_link_pkg::USED_BYTES;

    logic clk = 0;
    always #5 clk = ~clk;
    int unsigned cyc = 0;
    always @(posedge clk) cyc++;

    logic [7:0] led;
    wire  [31:0] fmc_pins;
    logic rxd, txd;
    logic [4:0] jumper = 5'b11111;

    phase7_link_top #(.BAUD(BAUD)) dut (.clk(clk), .led(led), .fmc_pins(fmc_pins), .rxd(rxd), .txd(txd));

    genvar g;
    generate
        for (g = 0; g < 5; g = g + 1) begin : g_jumper
            assign fmc_pins[g + 16] = jumper[g] ? fmc_pins[g] : 1'b0;
        end
    endgenerate

    // ---- mock PC ----
    logic [7:0] pc_tx_data, pc_rx_data;
    logic pc_tx_send = 0, pc_tx_busy, pc_rx_valid, pc_rx_err;
    uart_tx #(.BAUD(BAUD)) u_pc_tx (.clk(clk), .rst_n(1'b1), .data_in(pc_tx_data), .send(pc_tx_send),
                                    .busy(pc_tx_busy), .tx(rxd));
    uart_rx #(.BAUD(BAUD)) u_pc_rx (.clk(clk), .rst_n(1'b1), .rx(txd), .data_out(pc_rx_data),
                                    .valid(pc_rx_valid), .frame_error(pc_rx_err));

    int fails = 0, checks = 0;
    task automatic check(input logic cond, input string msg);
        checks++;
        if (cond) $display("  PASS: %s", msg);
        else begin $display("  FAIL: %s", msg); fails++; end
    endtask
    task automatic tick(input int n = 1);
        repeat (n) begin @(posedge clk); #1; end
    endtask

    // the encoded table (from the generator) and a frame payload buffer
    function automatic logic [7:0] table_img(input int b);
        return phase7_link_tb_pkg::TABLE[b*8 +: 8];
    endfunction
    logic [7:0] fbuf [0:255];
    int n_steps_img;

    task automatic pc_send_byte(input logic [7:0] b);
        while (pc_tx_busy) tick(1);
        pc_tx_data = b; pc_tx_send = 1; tick(1); pc_tx_send = 0; tick(1);
    endtask

    // frame from fbuf[0:len-1]
    task automatic pc_send_frame(input logic [7:0] cmd, input logic [15:0] addr, input int len);
        logic [7:0] ck;
        ck = cmd ^ addr[7:0] ^ addr[15:8] ^ 8'(len);
        pc_send_byte(8'hAA); pc_send_byte(cmd); pc_send_byte(addr[7:0]); pc_send_byte(addr[15:8]);
        pc_send_byte(8'(len));
        for (int i = 0; i < len; i++) begin ck = ck ^ fbuf[i]; pc_send_byte(fbuf[i]); end
        pc_send_byte(ck);
        while (pc_tx_busy) tick(1);
    endtask

    logic [7:0] resp [0:63];
    int resp_n;
    task automatic pc_recv(input int total);
        resp_n = 0;
        for (int i = 0; i < 200_000 && resp_n < total; i++) begin
            tick(1);
            if (pc_rx_valid) begin resp[resp_n] = pc_rx_data; resp_n++; end
        end
        if (resp_n < total) begin $display("  FAIL: timed out on a %0d-byte response (%0d)", total, resp_n); fails++; checks++; end
    endtask

    task automatic write_bytes(input logic [15:0] addr, input int len);   // payload in fbuf
        pc_send_frame(8'h01, addr, len);
        tick(len + 10);   // let the bus writes land (LEN+4 ticks, link_frame.sv)
    endtask
    task automatic write_byte(input logic [15:0] addr, input logic [7:0] v);
        fbuf[0] = v; write_bytes(addr, 1);
    endtask
    task automatic read_bytes(input logic [8:0] cmd, input logic [15:0] addr, input int len);
        for (int i = 0; i < len; i++) fbuf[i] = 0;
        pc_send_frame(cmd[7:0], addr, len);
        pc_recv(len + 6);
    endtask
    function automatic logic [7:0] status();
        return resp[5];
    endfunction
    task automatic read_status(output logic [7:0] s);
        pc_send_frame(8'h07, 16'h0000, 0);
        pc_recv(7);
        s = resp[5];
    endtask
    task automatic wait_not_busy(output logic [7:0] s);
        s = 8'h02;
        for (int i = 0; i < 400 && s[1]; i++) begin tick(2000); read_status(s); end
    endtask

    // ---- pin / step monitors (negedge: DUT registers settled) ----
    int unsigned apply_cyc [0:15];
    int n_apply, clk_rises, rst_falls;
    int unsigned rst_fall, rst_rise;
    logic [4:0] p_d = 0;
    task automatic clear_mon(); n_apply = 0; clk_rises = 0; rst_falls = 0; rst_fall = 0; rst_rise = 0; endtask
    always @(negedge clk) begin
        if (dut.step_start) begin apply_cyc[n_apply] = cyc; n_apply++; end
        if (dut.busy) begin
            if (fmc_pins[0] && !p_d[0]) clk_rises++;
            if (!fmc_pins[1] && p_d[1]) begin rst_falls++; rst_fall = cyc; end
            if (fmc_pins[1] && !p_d[1]) rst_rise = cyc;
        end
        p_d = fmc_pins[4:0];
    end

    function automatic int unsigned img32(input int step, input int off);
        return {table_img(step*EB+off+3), table_img(step*EB+off+2), table_img(step*EB+off+1), table_img(step*EB+off)};
    endfunction

    initial begin #(200ms); $display("FAIL: watchdog"); $finish; end

    initial begin
        logic [7:0] s;
        n_steps_img = phase7_link_tb_pkg::N_STEPS;
        clear_mon();
        tick(50);

        $display("\n== 1. echo, load the table, APPLY ==");
        write_byte(16'h0000, 8'h5A);
        read_bytes(9'h02, 16'h0000, 1);
        check(resp[0] == 8'hAA && resp[1] == 8'h02 && resp[5] == 8'h5A, "SCRATCH write/readback over UART");
        for (int k = 0; k < n_steps_img; k++) begin
            for (int i = 0; i < UB; i++) fbuf[i] = table_img(k*EB + i);
            write_bytes(16'(phase7_link_pkg::TABLE_BASE + k*EB), UB);
        end
        write_byte(phase7_link_pkg::REG_N_STEPS, 8'(n_steps_img));
        read_bytes(9'h02, phase7_link_pkg::REG_N_STEPS, 1);
        check(resp[5] == 8'(n_steps_img), $sformatf("N_STEPS reads back %0d", resp[5]));
        pc_send_frame(8'h04, 16'h0000, 0);   // APPLY = re-apply step 0, RUN low
        tick(200);
        check(fmc_pins[1] == 1'b1 && fmc_pins[0] == 0 && fmc_pins[4] == 0,
              "after APPLY: pins at the loaded table's step 0 (rst 1, others 0)");
        read_status(s);
        check(s == 8'h00, $sformatf("STATUS idle, no flags (%b)", s));

        $display("\n== 2. RUN the loaded sequence ==");
        clear_mon();
        pc_send_frame(8'h05, 16'h0000, 0);   // RUN = start
        wait_not_busy(s);
        check(s[2] && !s[3] && !s[4], $sformatf("STATUS: done, no fault/abort (%b)", s));
        check(n_apply == n_steps_img, $sformatf("%0d step starts", n_apply));
        check(apply_cyc[1] - apply_cyc[0] == img32(0, phase7_link_pkg::H_COND_ARG),
              $sformatf("step 0 lasted exactly %0d ticks (%0d)", img32(0, phase7_link_pkg::H_COND_ARG), apply_cyc[1] - apply_cyc[0]));
        check(apply_cyc[2] - apply_cyc[1] == img32(1, phase7_link_pkg::H_COND_ARG),
              $sformatf("step 1 lasted exactly %0d ticks (%0d)", img32(1, phase7_link_pkg::H_COND_ARG), apply_cyc[2] - apply_cyc[1]));
        check(rst_falls == 1 && rst_rise - rst_fall == img32(1, phase7_link_pkg::RST_BASE + phase7_link_pkg::F_SIG_PARAM_A),
              $sformatf("rst low once, for %0d ticks", rst_rise - rst_fall));
        check(clk_rises == 8, $sformatf("clk: 8 rising edges (%0d)", clk_rises));
        check(s[5] && apply_cyc[5] - apply_cyc[4] > 3,
              $sformatf("LATE set: 'confirm' ended after 3 ticks, step 5 waited for the bank (%0d ticks)", apply_cyc[5] - apply_cyc[4]));
        read_bytes(9'h08, 16'(2 * phase7_link_pkg::CAP_STRIDE + phase7_link_pkg::CAP_DATA), 2);
        check({resp[6], resp[5]} == 16'h00A5, $sformatf("data_in read over the link = %h", {resp[6], resp[5]}));
        read_bytes(9'h02, phase7_link_pkg::REG_LAST_STEP, 1);
        check(resp[5] == 8'd5, $sformatf("LAST_STEP = 5 (%0d)", resp[5]));

        $display("\n== 3. writes while running are refused ==");
        pc_send_frame(8'h05, 16'h0000, 0);
        tick(2000);
        write_byte(phase7_link_pkg::REG_N_STEPS, 8'd2);
        write_byte(16'(phase7_link_pkg::TABLE_BASE + 5), 8'hFF);
        read_status(s);
        check(s[1] && s[6], $sformatf("busy and TABLE_REJECTED set (%b)", s));
        wait_not_busy(s);
        read_bytes(9'h02, phase7_link_pkg::REG_N_STEPS, 1);
        check(resp[5] == 8'(n_steps_img) && s[2], "N_STEPS unchanged and that run still completed");
        write_byte(phase7_link_pkg::REG_STATUS, 8'h00);
        read_status(s);
        check(!s[6], "a STATUS write clears TABLE_REJECTED");

        $display("\n== 4. jumper J2-20 (en) pulled ==");
        jumper[4] = 1'b0;
        pc_send_frame(8'h05, 16'h0000, 0);
        wait_not_busy(s);
        read_bytes(9'h02, phase7_link_pkg::REG_LAST_STEP, 1);
        check(s[3] && !s[2] && resp[5] == 8'd4, $sformatf("FAULT at step 4 (status %b, last %0d)", s, resp[5]));
        check(led[5] && fmc_pins[4] == 0 && fmc_pins[1] == 1, "LD5 on; pins back to step 0");
        jumper[4] = 1'b1;

        $display("\n== 5. STOP during step 2 ==");
        pc_send_frame(8'h05, 16'h0000, 0);
        while (dut.step != 2) tick(1);
        tick(500);
        pc_send_frame(8'h06, 16'h0000, 0);   // STOP = abort
        tick(200);
        read_status(s);
        read_bytes(9'h02, phase7_link_pkg::REG_LAST_STEP, 1);
        check(s[4] && !s[1] && resp[5] == 8'd2, $sformatf("ABORTED at step 2 (status %b, last %0d)", s, resp[5]));
        check(fmc_pins[0] == 0 && fmc_pins[2] == 0 && fmc_pins[1] == 1, "pins back to step 0 after the abort");
        check(!led[7], "no UART framing error / FIFO overflow (LD7 off)");

        $display("\n================================================");
        if (fails == 0) $display("ALL TESTS PASSED (%0d checks)", checks);
        else $display("%0d CHECK(S) FAILED out of %0d", fails, checks);
        $display("================================================\n");
        $finish;
    end

endmodule
